@PreAuthorize("isAuthenticated()")
public ResponseEntity<List<Order>> getMyOrders(int limit, Authentication authentication) {
    String customerId = authentication == null ? null : authentication.getName();
    if (customerId == null || customerId.isBlank()) {
        return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
    }
    limit = Math.max(1, Math.min(limit, 100));
    Pageable page = PageRequest.of(0, limit, Sort.by("id"));
    List<Order> orders = orderRepository.findByCustomerId(customerId, page);
    return ResponseEntity.ok(orders);
}

